        mismatches.check(
            H.repeating(value),
            H(raw: HighwayReference.repeatingU16(value)),
            "repeating"
        )
        for (mask, a) in everyPair(maskInputs, aInputs) {
            mismatches.check(
                H.multiplying(a, H.repeating(value), where: mask),
                H(
                    raw: HighwayReference.multiplyingWhereU16(
                        mask.raw,
                        a.raw,
                        H.repeating(value).raw
                    )
                ),
                "mask: \(describe(mask)), a: \(describe(a))"
            )
        }
        mismatches.record()
    }

