    @inline(__always)
    private func checkMultiplyingWhereConstantAAlternating(_ even: Lane, _ odd: Lane) {
        let mismatches = Mismatches("multiplyingWhere with a alternating \(hex(even)), \(hex(odd))")
        let maskInputs = Inputs.masks(H.Mask.self, seed: 0x86AA_4B73_3B9C_F410)
        let bInputs = Inputs.vectors(H.self, seed: 0x86AA_4D73_3B9C_F776)
        mismatches.check(
            H.repeatingBlock(even, odd, even, odd, even, odd, even, odd),
            H(raw: HighwayReference.repeatingBlockU16(even, odd, even, odd, even, odd, even, odd)),
            "repeatingBlock"
        )
        for (mask, b) in everyPair(maskInputs, bInputs) {
            mismatches.check(
                H.multiplying(
                    H.repeatingBlock(even, odd, even, odd, even, odd, even, odd),
                    b,
                    where: mask
                ),
                H(
                    raw: HighwayReference.multiplyingWhereU16(
                        mask.raw,
                        H.repeatingBlock(even, odd, even, odd, even, odd, even, odd).raw,
                        b.raw
                    )
                ),
                "mask: \(describe(mask)), b: \(describe(b))"
            )
        }
        mismatches.record()
    }

