    @inline(__always)
    private func checkMultiplyAddingWhereConstantMask(_ mask: H.Mask) {
        let mismatches = Mismatches("multiplyAddingWhere with mask \(describe(mask))")
        let aInputs = Inputs.vectors(H.self, seed: 0x3CA5_9AA0_0792_5210)
        let bInputs = Inputs.vectors(H.self, seed: 0x3CA5_9DA0_0792_5729)
        let cInputs = Inputs.vectors(H.self, seed: 0x3CA5_9CA0_0792_5576)
        for (a, b, c) in mixedTriples(aInputs, bInputs, cInputs, seed: 0x4156_24E5_1836_9EC5) {
            mismatches.check(
                H.multiplyAdding(a, b, c, where: mask),
                H(raw: HighwayReference.multiplyAddingWhereU16(mask.raw, a.raw, b.raw, c.raw)),
                "a: \(describe(a)), b: \(describe(b)), c: \(describe(c))"
            )
        }
        mismatches.record()
    }

